-- MySQL 8.0.46. Store AI assistance as an unapproved suggestion for human review.
CREATE TABLE TicketAIAnalysis (MaAnalysis INT AUTO_INCREMENT PRIMARY KEY, MaTicket INT NOT NULL, MaUser INT NOT NULL, RequestKey CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, RequestHash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, CategorySuggestion VARCHAR(100) NOT NULL, PrioritySuggestion VARCHAR(30) NOT NULL, SentimentSuggestion VARCHAR(30) NOT NULL, DraftReply LONGTEXT NOT NULL, Summary LONGTEXT NOT NULL, Provider VARCHAR(20) NOT NULL, Model VARCHAR(100) NOT NULL, ReviewStatus VARCHAR(20) NOT NULL DEFAULT 'Pending', ReviewedBy INT NULL, CreatedAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), ReviewedAt DATETIME(3) NULL, CONSTRAINT FK_TicketAI_Ticket FOREIGN KEY(MaTicket) REFERENCES Ticket(MaTicket), CONSTRAINT FK_TicketAI_User FOREIGN KEY(MaUser) REFERENCES UserAccount(MaUser), CONSTRAINT FK_TicketAI_Reviewer FOREIGN KEY(ReviewedBy) REFERENCES UserAccount(MaUser), CONSTRAINT UQ_TicketAI_Request UNIQUE(MaUser,RequestKey), CONSTRAINT CK_TicketAI_Priority CHECK(PrioritySuggestion IN ('Thấp','Trung bình','Cao','Khẩn cấp')), CONSTRAINT CK_TicketAI_Sentiment CHECK(SentimentSuggestion IN ('Tích cực','Trung tính','Tiêu cực')), CONSTRAINT CK_TicketAI_Review CHECK(ReviewStatus IN ('Pending','Selected','Dismissed')), INDEX IX_TicketAI_TicketTime(MaTicket,CreatedAt)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;